      document.querySelectorAll('.pp-tiers .tiers-donut').forEach(donut => {
        const legend = Array.from(donut.parentElement.querySelectorAll('.tiers-legend > div'));
        const rows = legend.map(div => {
          const stats = flatText(div.querySelector('b'));
          return {
            name: flatText(div.querySelector('span')),
            stats,
            share: parseFloat((stats.split('·').pop() || '').trim()) || 0,
            node: div
          };
        });
        if (!rows.length) return;
        let acc = 0;
        rows.forEach(r => { acc += r.share; r.upto = acc; });
        setTip(donut, '\u00a0', '\u00a0');
        const paint = event => {
          const box = donut.getBoundingClientRect();
          // conic-gradient starts at 12 o'clock and runs clockwise, the same
          // order as the legend rows, so the cursor's bearing converts straight
          // to a 0-100 share and is matched against the rows' cumulative share.
          // The ring SPINS (CSS animation), so the gradient's 12 o'clock has moved away
          // from the top. Read the element's live rotation off its computed matrix and take
          // it back out of the cursor bearing first - without this the ring resolves the
          // cursor to the WRONG tier and the tooltip names the wrong band.
          let spin = 0;
          {
            const _tr = getComputedStyle(donut).transform;
            if (_tr && _tr !== 'none') {
              const _m = _tr.match(/matrix\(([^)]+)\)/);
              if (_m) {
                const _v = _m[1].split(',').map(Number);
                spin = Math.atan2(_v[1], _v[0]) * 180 / Math.PI;
              }
            }
          }
          const bearing = ((Math.atan2(event.clientY - (box.top + box.height / 2),
                                      event.clientX - (box.left + box.width / 2)) * 180 / Math.PI
                           + 450 - spin) % 360 + 360) % 360;
          // Pointer coordinates arrive as whole pixels while the ring's centre is
          // fractional, so a cursor on the top edge of the ring measures a hair
          // clockwise of 12 o'clock (359.75 on a 170px ring) and would resolve to
          // the 0.4% sliver rather than the arc the top of the ring shows. Snap
          // one rim pixel's worth of slop back to the first slice.
          const slop = Math.atan(1 / (box.width / 2)) * 180 / Math.PI;
          const pct = bearing > 360 - slop ? 0 : bearing / 3.6;
          const tier = rows.find(r => pct <= r.upto + 1e-4) || rows[rows.length - 1];
          donut.setAttribute('data-tooltip-en', `<b>${tier.name} tier</b><br>${tier.stats}`);
          donut.setAttribute('data-tooltip-cn', `<b>${cnTip(tier.name)}分层</b><br>${tier.stats}`);
          if (activeTooltipTarget === donut) {
            tooltip.innerHTML = donut.getAttribute(tooltipLanguage === 'cn' ? 'data-tooltip-cn' : 'data-tooltip-en');
            positionTooltip(event);
          }
        };
        donut.addEventListener('mouseenter', paint);
        donut.addEventListener('mousemove', paint);
        rows.forEach(r => setTip(r.node, `<b>${r.name} tier</b><br>${r.stats}`,
                                        `<b>${cnTip(r.name)}分层</b><br>${r.stats}`));
      });

